response:
[
  {
    "id": 1,
    "source": "selbstverständlich für einen Politiker wie ihn,",
    "text": "برای سیاستمداری مانند او امری بدیهی است"
  },
  {
    "id": 2,
    "source": "keine Angriffe auf den liberalen Konsens und das amerikanische Sozialsystem.",
    "text": "بدون حمله به اجماع لیبرال و سیستم رفاه اجتماعی آمریکا"
  },
  {
    "id": 3,
    "source": "Auf dem Parteitag in Miami schlägt Nixon Reagan vernichtend.",
    "text": "در کنگره حزب در میامی، نیکسون، ریگان را قاطعانه شکست می‌دهد"
  },
  {
    "id": 4,
    "source": "Dieser erhält nur 15 Prozent der Delegiertenstimmen.",
    "text": "او تنها ۱۵ درصد آرای نمایندگان را به دست می‌آورد"
  },
  {
    "id": 5,
    "source": "Damit sind die Konservativen in ihre Schranken verwiesen worden.",
    "text": "بدین ترتیب محافظه‌کاران به جایگاه خود محدود شدند"
  },
  {
    "id": 6,
    "source": "Innerhalb einer republikanischen Partei, die nach wie vor den liberalen Werten verbunden ist.",
    "text": "درون حزب جمهوری‌خواهی که همچنان به ارزش‌های لیبرال پایبند است"
  },
  {
    "id": 7,
    "source": "Am 5. November 1968 besiegt Richard Nixon den Demokraten Hubert Humphrey und wird zum US-Präsidenten gewählt.",
    "text": "در ۵ نوامبر ۱۹۶۸، ریچارد نیکسون بر هوبرت هامفری دموکرات پیروز شده و به عنوان رئیس‌جمهور آمریکا انتخاب می‌شود"
  },
  {
    "id": 8,
    "source": "Maker of the world's most complete line of electronic calculators, the LC-8.",
    "text": "سازنده کامل‌ترین سری ماشین‌حساب‌های الکترونیکی جهان، مدل LC-8"
  },
  {
    "id": 9,
    "source": "World's smallest electronic calculator by Sharp.",
    "text": "کوچک‌ترین ماشین‌حساب الکترونیکی جهان از شرکت شارپ"
  },
  {
    "id": 10,
    "source": "Price tag to match, $345. Complete.",
    "text": "با قیمت متناسب، ۳۴۵ دلار. کامل"
  },
  {
    "id": 11,
    "source": "See it.",
    "text": "آن را ببینید"
  },
  {
    "id": 12,
    "source": "So help me God.",
    "text": "خداوند مرا یاری کند"
  },
  {
    "id": 13,
    "source": "Von Beginn an gelobt Nixon Transparenz.",
    "text": "نیکسون از همان ابتدا وعده شفافیت می‌دهد"
  },
  {
    "id": 14,
    "source": "Er werde den Amerikanern stets die Wahrheit sagen.",
    "text": "اینکه او همیشه حقیقت را به آمریکایی‌ها خواهد گفت"
  },
  {
    "id": 15,
    "source": "In einer für die USA neuartigen Zeremonie stellt er seine Minister vor.",
    "text": "او در مراسمی که برای آمریکا تازگی داشت، وزرای خود را معرفی می‌کند"
  },
  {
    "id": 16,
    "source": "Er versichert vor dem ganzen Land, er werde immer auf sie hören.",
    "text": "او در برابر کل کشور اطمینان می‌دهد که همیشه به حرف آن‌ها گوش خواهد داد"
  },
  {
    "id": 17,
    "source": "Kaum hat er das gesagt, weist er seinen Stabschef an.",
    "text": "هنوز این را نگفته، به رئیس دفتر خود دستور می‌دهد"
  },
  {
    "id": 18,
    "source": "Halte sie alle von mir fern.",
    "text": "همه آن‌ها را از من دور نگه دار"
  },
  {
    "id": 19,
    "source": "Nixon regiert allein und im Geheimen.",
    "text": "نیکسون تنها و در خفا حکومت می‌کند"
  },
  {
    "id": 20,
    "source": "Gleich nach Amtsantritt ordnet er die bis dahin intensivsten Bombardierungen an,",
    "text": "بلافاصله پس از آغاز به کار، او دستور شدیدترین بمباران‌های تا آن زمان را صادر می‌کند"
  },
  {
    "id": 21,
    "source": "um die Versorgungslinien des Vietkongs in Kambodscha abzuschneiden.",
    "text": "تا خطوط تدارکاتی ویت‌کنگ در کامبوج را قطع کند"
  },
  {
    "id": 22,
    "source": "Er informiert weder den Kongress noch seinen Verteidigungsminister darüber.",
    "text": "او نه کنگره و نه وزیر دفاع خود را در این باره مطلع نمی‌کند"
  },
  {
    "id": 23,
    "source": "Heimlich verschärft er den Krieg, um aus einer Position der Stärke heraus Frieden aushandeln zu können.",
    "text": "او مخفیانه جنگ را تشدید می‌کند تا بتواند از موضع قدرت برای صلح مذاکره کند"
  },
  {
    "id": 24,
    "source": "Doch indem er diese geheime Operation in Kambodscha verschweigt, hintergeht er den Kongress und die Bürger.",
    "text": "اما با پنهان کردن این عملیات سری در کامبوج، به کنگره و شهروندان خیانت می‌کند"
  },
  {
    "id": 25,
    "source": "Im Jahr 1969 sterben rund 11.700 amerikanische Soldaten in Vietnam.",
    "text": "در سال ۱۹۶۹ حدود ۱۱۷۰۰ سرباز آمریکایی در ویتنام کشته می‌شوند"
  },
  {
    "id": 26,
    "source": "Damit steigt die Gesamtzahl der Opfer seit Kriegsbeginn auf mehr als 40.000 Tote und 250.000 Verwundete.",
    "text": "بدین ترتیب مجموع قربانیان از آغاز جنگ به بیش از ۴۰ هزار کشته و ۲۵۰ هزار مجروح می‌رسد"
  },
  {
    "id": 27,
    "source": "Die Studierenden verstärken ihre Proteste gegen den Krieg.",
    "text": "دانشجویان اعتراضات خود علیه جنگ را تشدید می‌کنند"
  },
  {
    "id": 28,
    "source": "Vor allem in Kalifornien, wo Gouverneur Reagan regelmäßig Öl ins Feuer gießt.",
    "text": "به ویژه در کالیفرنیا، جایی که فرماندار ریگان مرتباً بر آتش اختلافات می‌دمد"
  },
  {
    "id": 29,
    "source": "Tatsächlich ist es eine durchdachte Strategie.",
    "text": "در واقع این یک استراتژی حساب‌شده است"
  },
  {
    "id": 30,
    "source": "All das könnte Gouverneur Reagan politisch nützen.",
    "text": "همه این‌ها می‌تواند به نفع سیاسی فرماندار ریگان باشد"
  }
]

[
  {
    "id": 1,
    "source": "Seine harte Haltung gegenüber den Demonstranten gefällt den meisten kalifornischen Wählern.",
    "text": "موضع سرسختانه او در برابر معترضان، مورد پسند اکثر رأی‌دهندگان کالیفرنیایی است"
  },
  {
    "id": 2,
    "source": "Reagans Beliebtheit steigt jedes Mal, wenn er das Vorgehen verschärft.",
    "text": "محبوبیت ریگان هر بار که او اقدامات خود را تشدید می‌کند، افزایش می‌یابد"
  },
  {
    "id": 3,
    "source": "Für Nixon die Bestätigung, dass ein Teil der öffentlichen Meinung gegen die Pazifisten radikaler wird.",
    "text": "برای نیکسون این تأییدی است بر اینکه بخشی از افکار عمومی علیه صلح‌طلبان رادیکال‌تر می‌شود"
  },
  {
    "id": 4,
    "source": "Das will er nutzen, denn er muss seine Absichten bezüglich des Vietnamkriegs offenlegen.",
    "text": "او می‌خواهد از این موضوع استفاده کند، زیرا باید نیات خود را در مورد جنگ ویتنام آشکار سازد"
  },
  {
    "id": 5,
    "source": "Good evening, my fellow Americans.",
    "text": "عصر بخیر، هموطنان آمریکایی من"
  },
  {
    "id": 6,
    "source": "Tonight I want to talk to you on a subject of deep concern to all Americans and to many people in all parts of the",
    "text": "امشب می‌خواهم با شما درباره موضوعی صحبت کنم که دغدغه عمیق همه آمریکایی‌ها و بسیاری از مردم در تمام نقاط"
  },
  {
    "id": 7,
    "source": "world, the war in Vietnam.",
    "text": "جهان است، جنگ در ویتنام"
  },
  {
    "id": 8,
    "source": "For the future of peace, a precipitate withdrawal would be a disaster of immense magnitude.",
    "text": "برای آینده صلح، خروج شتاب‌زده فاجعه‌ای با ابعاد عظیم خواهد بود"
  },
  {
    "id": 9,
    "source": "A nation cannot remain great if it betrays its allies and lets down its friends.",
    "text": "یک ملت نمی‌تواند بزرگ بماند اگر به متحدانش خیانت کند و دوستانش را ناامید سازد"
  },
  {
    "id": 10,
    "source": "We have adopted a plan which we have worked out in cooperation with the South Vietnamese",
    "text": "ما طرحی را اتخاذ کرده‌ایم که با همکاری ویتنام جنوبی تدوین کرده‌ایم"
  },
  {
    "id": 11,
    "source": "for the complete withdrawal of all U.S.",
    "text": "برای خروج کامل تمام نیروهای"
  },
  {
    "id": 12,
    "source": "Combat ground forces and their replacement by South Vietnamese forces on an orderly scheduled timetable.",
    "text": "رزمی زمینی ایالات متحده و جایگزینی آن‌ها با نیروهای ویتنام جنوبی طبق یک جدول زمانی منظم"
  },
  {
    "id": 13,
    "source": "Jeder Amerikaner versteht, es wird Jahre dauern und viele GIs werden dabei ihr Leben lassen.",
    "text": "هر آمریکایی می‌فهمد که این کار سال‌ها طول خواهد کشید و بسیاری از سربازان آمریکایی جان خود را از دست خواهند داد"
  },
  {
    "id": 14,
    "source": "Als Reaktion auf die Rede fordern zwei Millionen Amerikaner die sofortige Rückkehr der US-Soldaten.",
    "text": "در واکنش به این سخنرانی، دو میلیون آمریکایی خواستار بازگشت فوری سربازان آمریکایی شدند"
  },
  {
    "id": 15,
    "source": "Die größte Demonstration seit Kriegsbeginn.",
    "text": "بزرگترین تظاهرات از آغاز جنگ"
  },
  {
    "id": 16,
    "source": "Viele Menschen sagen, diese Demonstration spiegelt nicht die Ansicht von 200 Millionen Amerikanern wider.",
    "text": "بسیاری می‌گویند این تظاهرات بازتاب‌دهنده دیدگاه ۲۰۰ میلیون آمریکایی نیست"
  },
  {
    "id": 17,
    "source": "Im Gegenteil.",
    "text": "برعکس"
  },
  {
    "id": 18,
    "source": "Manche Beobachter denken, die Demonstranten sprechen nur für eine Minderheit.",
    "text": "برخی ناظران فکر می‌کنند معترضان تنها به نمایندگی از یک اقلیت صحبت می‌کنند"
  },
  {
    "id": 19,
    "source": "Die schweigende Mehrheit unterstütze das amerikanische Vorgehen in Vietnam.",
    "text": "اکثریت خاموش از اقدام آمریکا در ویتنام حمایت می‌کند"
  },
  {
    "id": 20,
    "source": "Nixon hat offenbar recht.",
    "text": "ظاهراً نیکسون حق دارد"
  },
  {
    "id": 21,
    "source": "Umfragen zeigen, 70 Prozent der Amerikaner identifizieren sich mit dieser schweigenden Mehrheit,",
    "text": "نظرسنجی‌ها نشان می‌دهد که ۷۰ درصد آمریکایی‌ها خود را با این اکثریت خاموش هم‌هویت می‌دانند،"
  },
  {
    "id": 22,
    "source": "um deren Unterstützung erwirbt.",
    "text": "که حمایتش را به دست می‌آورد"
  },
  {
    "id": 23,
    "source": "Der Ausdruck ist nun in aller Munde in diesem zurückhaltenden Teil Amerikas.",
    "text": "این اصطلاح اکنون در این بخش محتاط آمریکا بر سر زبان‌ها افتاده است"
  },
  {
    "id": 24,
    "source": "Dem Nixon es dadurch leichter macht, sich offen zu äußern.",
    "text": "که باعث می‌شود نیکسون راحت‌تر بتواند آشکارا ابراز نظر کند"
  },
  {
    "id": 25,
    "source": "The silent majority, they've got too many things on their mind.",
    "text": "اکثریت خاموش، آن‌ها دغدغه‌های زیادی در ذهن دارند"
  },
  {
    "id": 26,
    "source": "Paying their taxes, seeing that their kids are all right, not in trouble.",
    "text": "پرداخت مالیات، اطمینان از اینکه فرزندانشان حالشان خوب است و دچار دردسر نمی‌شوند"
  },
  {
    "id": 27,
    "source": "They work real hard. Maybe their wives are working, too.",
    "text": "آن‌ها خیلی سخت کار می‌کنند. شاید همسرانشان هم کار می‌کنند"
  },
  {
    "id": 28,
    "source": "And just being, just trying to stay out of trouble and doing the right thing every day, day in and day out.",
    "text": "و فقط سعی می‌کنند از دردسر دور بمانند و هر روز، روز از پی روز، کار درست را انجام دهند"
  },
  {
    "id": 29,
    "source": "Es ist dieses Amerika, das eine jungen Leute in den Vietnamkrieg schickt,",
    "text": "این همان آمریکایی است که جوانان را به جنگ ویتنام می‌فرستد،"
  },
  {
    "id": 30,
    "source": "während die Kinder der Oberschicht studieren und vom Wehrdienst befreit sind.",
    "text": "در حالی که فرزندان طبقه مرفه تحصیل می‌کنند و از خدمت سربازی معاف هستند"
  }
]

[
  {
    "id": 1,
    "source": "The tallest building in the world.",
    "text": "بلندترین ساختمان جهان"
  },
  {
    "id": 2,
    "source": "Der amerikanische Durchschnittsarbeiter wird Joe genannt, der häufigste Vorname in Arbeiterfamilien.",
    "text": "کارگر متوسط آمریکایی «جو» نامیده می‌شود، که رایج‌ترین نام کوچک در خانواده‌های کارگری است"
  },
  {
    "id": 3,
    "source": "Joe ist das schlagende Herz der amerikanischen Industrie.",
    "text": "جو قلب تپنده صنعت آمریکاست"
  },
  {
    "id": 4,
    "source": "Er ist gewerkschaftlich organisiert, gut bezahlt und der Hauptnutznießer des liberalen Konsens,",
    "text": "او عضو اتحادیه کارگری است، حقوق خوبی می‌گیرد و ذینفع اصلی اجماع لیبرالی است"
  },
  {
    "id": 5,
    "source": "den Amerika ursprünglich für ihn erfunden hat.",
    "text": "که آمریکا در اصل برای او ابداع کرده است"
  },
  {
    "id": 6,
    "source": "Joe ist in der Regel ein treuer Wähler der Demokraten und hat 1968 nicht für Nixon gestimmt.",
    "text": "جو معمولاً رأی‌دهنده وفادار دموکرات‌هاست و در سال ۱۹۶۸ به ریچارد نیکسون رأی نداد"
  },
  {
    "id": 7,
    "source": "1970 kommt Joe von John Avildsen in die Kinos.",
    "text": "در سال ۱۹۷۰ فیلم «جو» ساخته جان آویلدسن به سینماها می‌آید"
  },
  {
    "id": 8,
    "source": "Ein Low-Budget-Film, dessen überraschender Erfolg die Konflikte verdeutlicht,",
    "text": "یک فیلم کم‌هزینه که موفقیت غافلگیرکننده‌اش، تضادهایی را آشکار می‌کند"
  },
  {
    "id": 9,
    "source": "die die amerikanische Gesellschaft zerfressen.",
    "text": "که جامعه آمریکا را از درون می‌خورد"
  },
  {
    "id": 10,
    "source": "Das Leben des Managers Bill aus New York gerät aus den Fugen,",
    "text": "زندگی بیل، مدیر اهل نیویورک، از هم می‌پاشد"
  },
  {
    "id": 11,
    "source": "als seine 19-jährige Tochter Melissa mit einer Überdosis Heroin ins Krankenhaus eingeliefert wird.",
    "text": "وقتی دختر ۱۹ ساله‌اش ملیسا به دلیل مصرف بیش از حد هروئین در بیمارستان بستری می‌شود"
  },
  {
    "id": 12,
    "source": "Die Droge hat ihr ihr Freund besorgt.",
    "text": "دوست‌پسرش مواد را برای او تهیه کرده است"
  },
  {
    "id": 13,
    "source": "Bill will die Sachen seiner Tochter bei ihrem Freund und Dealer abholen.",
    "text": "بیل می‌خواهد وسایل دخترش را از دوست‌پسر و فروشنده مواد پس بگیرد"
  },
  {
    "id": 14,
    "source": "Es kommt zu Handgreiflichkeiten.",
    "text": "کار به درگیری فیزیکی می‌کشد"
  },
  {
    "id": 15,
    "source": "Blind vor Wut tötet Bill den jungen Mann.",
    "text": "بیل که از خشم کور شده، آن مرد جوان را می‌کشد"
  },
  {
    "id": 16,
    "source": "In einer nahegelegenen Bar will er wieder zu sich kommen und begegnet dem Arbeiter Joe,",
    "text": "او برای آرام شدن به باری در همان نزدیکی می‌رود و با جو، یک کارگر، ملاقات می‌کند"
  },
  {
    "id": 17,
    "source": "der die schwelende Wut Amerikas auf seine Jugend verkörpert.",
    "text": "که تجسم خشم فروخورده آمریکا نسبت به نسل جوانش است"
  },
  {
    "id": 18,
    "source": "Sex, drugs, pissing on America, fucking up the music.",
    "text": "سکس، مواد مخدر، ادرار کردن روی آمریکا، گند زدن به موسیقی"
  },
  {
    "id": 19,
    "source": "I like that kill one of them.",
    "text": "خوشم می‌آید که یکی‌شان را بکشم"
  },
  {
    "id": 20,
    "source": "I would.",
    "text": "من این کار را می‌کنم"
  },
  {
    "id": 21,
    "source": "I like to kill one of them.",
    "text": "دوست دارم یکی‌شان را بکشم"
  },
  {
    "id": 22,
    "source": "I just did.",
    "text": "همین الان کشتم"
  },
  {
    "id": 23,
    "source": "Why do you hear it?",
    "text": "چرا این را می‌شنوی؟"
  },
  {
    "id": 24,
    "source": "Are you serious?",
    "text": "جدی می‌گویی؟"
  },
  {
    "id": 25,
    "source": "Joe begreift, dass Bill gerade einen Mord begangen hat.",
    "text": "جو متوجه می‌شود که بیل همین الان مرتکب قتل شده است"
  },
  {
    "id": 26,
    "source": "Eine unwahrscheinliche Freundschaft zwischen dem Arbeiter und dem Manager entsteht.",
    "text": "یک دوستی بعید میان آن کارگر و مدیر شکل می‌گیرد"
  },
  {
    "id": 27,
    "source": "Zwei weiße Männer voller Groll, die finden, dass niemand in diesem verdammten Land mehr respektiert wird.",
    "text": "دو مرد سفیدپوست پر از کینه که معتقدند در این کشور لعنتی دیگر به هیچ‌کس احترام گذاشته نمی‌شود"
  },
  {
    "id": 28,
    "source": "Angefangen bei ihm selbst. Look at that.",
    "text": "از خودشان شروع کرده تا دیگران. به آن نگاه کن"
  },
  {
